"use client";

import * as React from "react";
import { useMorph } from "@/lib/cojeev-motion/use-morph";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import * as Primitive from "@radix-ui/react-hover-card";
import { useFlowAppearance } from "@/lib/cojeev-motion/use-flow";
import { ScrollArea } from "@/components/ui/scroll-area";
export type HoverCardProps = React.ComponentProps<typeof Primitive.Root>;
export function HoverCard(props: HoverCardProps) {
  return <Primitive.Root openDelay={300} closeDelay={150} {...props} />;
}
export type HoverCardTriggerProps = React.ComponentProps<
  typeof Primitive.Trigger
>;
export function HoverCardTrigger(props: HoverCardTriggerProps) {
  return (
    <Primitive.Trigger
      data-slot="hover-card-trigger"
      data-part="trigger"
      {...props}
    />
  );
}
export type HoverCardPortalProps = React.ComponentProps<
  typeof Primitive.Portal
>;
export function HoverCardPortal(props: HoverCardPortalProps) {
  return <Primitive.Portal {...props} />;
}
export const hoverCardContentVariants = cva(
  "v-popover [background:var(--popover)] [border-radius:var(--r-card)] [padding:var(--s-5)] [box-shadow:var(--shadow-float)] [border:1px_solid_var(--v-border)]",
);
export type HoverCardContentProps = React.ComponentProps<
  typeof Primitive.Content
> & {
  portal?: boolean;
  appearance?: "identity" | "preview" | "media";
  scrollable?: boolean;
};
export function HoverCardContent({
  className,
  ref,
  children,
  sideOffset = 8,
  align = "start",
  collisionPadding = 8,
  portal = true,
  appearance,
  scrollable = !!appearance,
  ...props
}: HoverCardContentProps) {
  const morphRef = useMorph<HTMLDivElement>("surfaces", ref);
  const flowRef = useFlowAppearance<HTMLDivElement>(true, morphRef, "grow");
  const ownsScroll = scrollable && !props.asChild;
  const content = (
    <Primitive.Content
      ref={flowRef}
      data-slot="hover-card-content"
      data-part="content"
      data-appearance={appearance}
      data-morph={appearance ? "both" : undefined}
      data-r={appearance ? "css" : undefined}
      data-scrollable={ownsScroll || undefined}
      sideOffset={sideOffset}
      align={align}
      collisionPadding={collisionPadding}
      className={cn(hoverCardContentVariants(), className)}
      {...props}
    >
      {ownsScroll ? (
        <ScrollArea
          variant="plain"
          className="v-hovercard-scroll"
          viewportProps={{ "aria-label": "Preview details" }}
        >
          {children}
        </ScrollArea>
      ) : (
        children
      )}
    </Primitive.Content>
  );
  return portal ? <Primitive.Portal>{content}</Primitive.Portal> : content;
}

@layer cojeev-states {
/* Cojeev authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
@media (prefers-reduced-motion: reduce) {
  [data-slot="hover-card"],
  [data-slot^="hover-card-"],
  [data-slot="hover-card"]::before,
  [data-slot="hover-card"]::after,
  [data-slot^="hover-card-"]::before,
  [data-slot^="hover-card-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

[data-slot="hover-card-content"],
[data-slot="hover-card-sub-content"] {
  min-width: min(200px, calc(100vw - 24px));
  max-width: calc(100vw - 24px);
  max-height: min(
    480px,
    var(--radix-hover-card-content-available-height, calc(100dvh - 32px))
  );
  overflow-y: auto;
  overscroll-behavior: contain;
  overflow-wrap: anywhere;
}
[data-slot="hover-card-item"] {
  min-width: 0;
  height: auto;
  min-height: 36px;
  white-space: normal;
}
[data-slot="hover-card-content"] {
  z-index: var(--z-popover);
}
[data-slot="hover-card-content"][data-appearance] {
  --mfill: var(--v-paper);
  --mstroke: var(--v-border);
  border-radius: 18px;
  width: min(340px, calc(100vw - 24px));
  color: var(--v-text);
  border: 0;
  isolation: isolate;
}
[data-slot="hover-card-content"][data-appearance].v-morph-live {
  background: transparent;
}
[data-slot="hover-card-content"][data-scrollable] {
  overflow: visible;
  padding: 0;
}
.v-hovercard-scroll[data-slot="scroll-area"] {
  --h: min(
    440px,
    var(--radix-hover-card-content-available-height, calc(100dvh - 32px))
  );
}
.v-hovercard-scroll.v-scroll.-plain[data-slot="scroll-area"]
  > [data-slot="scroll-area-viewport"] {
  padding: 22px 28px 22px 22px;
}
.v-hovercard-detail {
  display: grid;
  gap: 15px;
}
.v-hovercard-detail h3 {
  margin: 0;
  font-family: var(--font-display);
  font-size: 22px;
  line-height: 1.25;
}
.v-hovercard-detail p {
  margin: 0;
  font-size: 13px;
  line-height: 1.65;
  color: var(--v-text-2);
}
.v-hovercard-detail__top {
  display: flex;
  align-items: center;
  gap: 14px;
}
.v-hovercard-detail__meta {
  display: block;
  font-size: 11px;
  color: var(--v-text-3);
  letter-spacing: 0.04em;
}
.v-hovercard-detail__excerpt {
  border-left: 3px solid var(--v-pink);
  padding-left: 13px;
}
.v-hovercard-detail__art {
  width: 100%;
  height: auto;
  display: block;
  border-radius: 10px;
}
.v-hovercard-detail__footer {
  border-top: 1px solid var(--v-edge);
  padding-top: 12px;
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.v-hovercard-example {
  display: grid;
  gap: 22px;
  width: 100%;
  max-width: 580px;
  margin-inline: auto;
  padding: 24px;
  background: var(--v-paper);
  border: 1px solid var(--v-edge);
  border-radius: 22px;
  color: var(--v-text);
}
.v-hovercard-example h3 {
  font-family: var(--font-display);
  margin: 0;
  font-size: 28px;
  line-height: 1.25;
}
.v-hovercard-example p {
  margin: 0;
  line-height: 1.6;
}
.v-hovercard-example > .v-btn {
  justify-self: start;
}
.v-hovercard-inline[data-slot="collapsible-content"] {
  padding: 0;
  background: transparent;
}
.v-hovercard-inline [data-disclosure-inner] {
  padding: 22px 0 0;
}
.v-hovercard-example__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.v-hovercard-example [data-slot="hover-card-trigger"] {
  min-height: 44px;
}

}
